"""
FastAPI 应用工厂

创建并配置 FastAPI 应用实例，包括:
- CORS 中间件
- REST 路由注册
- WebSocket 路由注册
- JobManager 状态注入
- 静态文件挂载 (生产环境)
"""

from __future__ import annotations

import os
from collections.abc import AsyncIterator
from contextlib import asynccontextmanager
from pathlib import Path

from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware
from fastapi.staticfiles import StaticFiles
from loguru import logger

from modfetch import __version__
from modfetch.adapters.download.retry import RetryPolicy
from modfetch.adapters.jobs import JobApplicationService
from modfetch.adapters.modrinth import ModrinthClient
from modfetch.domain.config_models import ModFetchConfig
from modfetch.ports.catalog import CatalogPort
from modfetch.server.routes import router as api_router
from modfetch.server.ws import router as ws_router


def _default_validation_catalog(config: ModFetchConfig) -> CatalogPort:
    """按配置的重试参数构造临时 catalog（供远端校验使用）

    与 CLI/构建路径策略一致：max_retries/retry_delay 直接驱动
    ModrinthClient 的重试策略；每次校验请求独立构造、用毕即关，
    避免共享 catalog 携带固定重试参数影响并发请求。
    """
    return ModrinthClient(
        retry=RetryPolicy(
            max_retries=config.max_retries,
            base_delay=config.retry_delay,
        )
    )


@asynccontextmanager
async def lifespan(app: FastAPI) -> AsyncIterator[None]:
    """应用生命周期钩子（替代弃用的 on_event）。

    startup：输出启动日志；
    shutdown：释放 catalog 持有的 Modrinth 连接。
    """
    logger.info("ModFetch API 服务启动")
    yield
    await app.state.catalog.close()
    logger.info("ModFetch API 服务关闭")


def create_app() -> FastAPI:
    """
    创建 FastAPI 应用实例

    工厂模式：每次调用返回独立应用实例，便于测试隔离与多实例部署。
    组装内容：
        - CORS 中间件：允许前端开发服务器跨域访问
        - app.state.job_manager：全局作业管理器（REST/WS 共享）
        - app.state.catalog：共享 Modrinth 客户端（REST 代理用）
        - REST 路由（/api/*）与 WebSocket 路由（/api/jobs/*/stream）
        - 生产环境静态文件挂载（Vue 构建输出 web/dist）
        - startup/shutdown 生命周期钩子（关闭时释放 catalog 连接）

    Returns:
        FastAPI: 配置好的应用实例
    """
    app = FastAPI(
        title="ModFetch API",
        description="Minecraft 模组下载管理工具 - REST API",
        version=__version__,
        lifespan=lifespan,
    )

    # CORS — 允许前端开发服务器访问
    app.add_middleware(
        CORSMiddleware,
        allow_origins=["*"],
        allow_credentials=True,
        allow_methods=["*"],
        allow_headers=["*"],
    )

    # 注入 JobManager 与共享 catalog。
    # catalog 注入默认 RetryPolicy(3 次)：Web 侧 validate_remote 等
    # 走 _request 的路径因此获得与下载侧一致的指数退避。
    # raw_get 路由代理保持裸透传（不重试）——前端需要精确 HTTP 语义。
    app.state.job_manager = JobApplicationService()
    app.state.catalog = ModrinthClient(retry=RetryPolicy())
    # 校验用 catalog 工厂：按配置的 max_retries/retry_delay 派生重试
    # 参数构造临时 client（/config/validate 与 /jobs 远端校验使用），
    # 测试可整体替换为离线桩以保持确定性。
    app.state.validation_catalog_factory = _default_validation_catalog

    # 注册 REST 路由
    app.include_router(api_router)

    # 注册 WebSocket 路由
    app.include_router(ws_router)

    # 静态文件挂载 (生产环境 — Vue 构建输出)
    web_dist = Path(__file__).parent.parent / "web" / "dist"
    if web_dist.is_dir():
        app.mount("/", StaticFiles(directory=str(web_dist), html=True), name="web")
        logger.info(f"已挂载静态文件: {web_dist}")
    else:
        logger.debug(f"静态文件目录不存在，跳过挂载: {web_dist}")

    return app
